effect.shader:
#define EPS 0.00001

float lum(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

// True CMY-RGB color balance
// This works on complementary color axes
// Cyan-Red: moving toward red adds red, removes cyan (green+blue)
// Magenta-Green: moving toward green adds green, removes magenta (red+blue)
// Yellow-Blue: moving toward blue adds blue, removes yellow (red+green)
vec3 balanceCMYRGB(vec3 rgb, float cr, float mg, float yb, float zoneMask) {
    if (abs(cr) < 0.5 && abs(mg) < 0.5 && abs(yb) < 0.5) return rgb;

    float crN = cr / 100.0;
    float mgN = mg / 100.0;
    float ybN = yb / 100.0;

    // Scale by zone mask so balance only applies where it should
    crN *= zoneMask;
    mgN *= zoneMask;
    ybN *= zoneMask;

    // Proper complementary axis math
    // Cyan-Red axis
    // Positive = more red = +R -G -B
    // Negative = more cyan = -R +G +B
    float rShift = crN * 0.1;
    float gShift = -crN * 0.05;
    float bShift = -crN * 0.05;

    // Magenta-Green axis
    // Positive = more green = -R +G -B
    // Negative = more magenta = +R -G +B
    gShift += mgN * 0.1;
    rShift -= mgN * 0.05;
    bShift -= mgN * 0.03;

    // Yellow-Blue axis
    // Positive = more blue = -R -G +B
    // Negative = more yellow = +R +G -B
    bShift += ybN * 0.1;
    rShift -= ybN * 0.03;
    gShift -= ybN * 0.05;

    rgb.r += rShift;
    rgb.g += gShift;
    rgb.b += bShift;

    return rgb;
}

// Per-zone saturation adjustment
// Works in RGB space to avoid HSL artifacts
vec3 adjustSaturation(vec3 rgb, float amount, float zoneMask) {
    if (abs(amount) < 0.5) return rgb;
    float a = amount / 100.0 * zoneMask;
    float l = lum(rgb);
    return mix(vec3(l), rgb, 1.0 + a);
}

// Per-zone brightness adjustment
// Preserves color ratios
vec3 adjustBrightness(vec3 rgb, float amount, float zoneMask) {
    if (abs(amount) < 0.5) return rgb;
    float a = amount / 100.0 * 0.3 * zoneMask;
    float l = lum(rgb);
    float origL = max(l, EPS);
    float newL = max(l + a, 0.0);
    return rgb * (newL / origL);
}

void main() {
    vec2 uv = acScreenNorm;
    vec4 original = texture2DCv(inputImg.texture, uv);
    vec3 rgb = max(original.rgb, 0.0);
    vec3 baseRGB = rgb;

    float l = lum(rgb);
    float origLum = l;

    // ═══ ZONE MASKS ═══
    // Smooth overlapping zones — no harsh transitions
    // Each zone fades smoothly into the next

    // Shadow zone — strongest at black, fades to zero at boundary
    float shMask = 1.0 - smoothstep(max(shBoundary - 0.15, 0.0), shBoundary + 0.05, l);

    // Highlight zone — zero below boundary, strongest at white
    float hlMask = smoothstep(hlBoundary - 0.05, min(hlBoundary + 0.15, 1.0), l);

    // Midtone zone — what's left between shadow and highlight
    // Peaks at center, zero at extremes
    float midMask = 1.0 - shMask - hlMask;
    midMask = max(midMask, 0.0);

    // Normalize so zones always sum to 1.0
    float totalMask = shMask + midMask + hlMask;
    if (totalMask > EPS) {
        shMask /= totalMask;
        midMask /= totalMask;
        hlMask /= totalMask;
    }

    // ═══ SHADOW COLOR BALANCE ═══
    vec3 shResult = balanceCMYRGB(rgb, shCyanRed, shMagGreen, shYelBlue, 1.0);
    shResult = adjustSaturation(shResult, shSatAdjust, 1.0);
    shResult = adjustBrightness(shResult, shLumAdjust, 1.0);

    // ═══ MIDTONE COLOR BALANCE ═══
    vec3 midResult = balanceCMYRGB(rgb, midCyanRed, midMagGreen, midYelBlue, 1.0);
    midResult = adjustSaturation(midResult, midSatAdjust, 1.0);
    midResult = adjustBrightness(midResult, midLumAdjust, 1.0);

    // ═══ HIGHLIGHT COLOR BALANCE ═══
    vec3 hlResult = balanceCMYRGB(rgb, hlCyanRed, hlMagGreen, hlYelBlue, 1.0);
    hlResult = adjustSaturation(hlResult, hlSatAdjust, 1.0);
    hlResult = adjustBrightness(hlResult, hlLumAdjust, 1.0);

    // ═══ COMBINE ZONES ═══
    vec3 result = shResult * shMask
                + midResult * midMask
                + hlResult * hlMask;

    // ═══ MASTER SATURATION ═══
    if (abs(masterSaturation - 100.0) > 0.5) {
        float ml = lum(result);
        result = mix(vec3(ml), result, masterSaturation / 100.0);
    }

    // ═══ MASTER BRIGHTNESS ═══
    if (abs(masterBrightness) > 0.5) {
        float mb = masterBrightness / 100.0 * 0.3;
        float rl = lum(result);
        float origRL = max(rl, EPS);
        float newRL = max(rl + mb, 0.0);
        result *= newRL / origRL;
    }

    // ═══ PRESERVE LUMINANCE ═══
    if (preserveLuminance) {
        float newLum = lum(result);
        if (newLum > EPS) {
            result *= origLum / newLum;
        }
    }

    // ═══ GLOBAL MIX ═══
    result = mix(baseRGB, result, globalMix);
    result = clamp(result, 0.0, 1.0);

    gl_FragColor = vec4(result, original.a);
}
